$string['settings:rag_chunksize'] = 'Ìwọ̀n Àjákù (àwọn ọ̀rọ̀)';
$string['settings:rag_chunksize_desc'] = 'Iye àwọn ọ̀rọ̀ tí a fojú sun fún àjákù àkóónú kọ̀ọ̀kan nígbà tí a bá ń ṣe àtọ́ka ohun èlò kọ́ọ̀sì. Àwọn àjákù kékeré péye sí i; àwọn àjákù ńlá ń pèsè àyíká ọ̀rọ̀ sí i.';
$string['settings:rag_return_scope'] = 'Àyè ìpadàbọ̀ fún ìwádìí';
$string['settings:rag_return_scope_desc'] = 'Ohun tí a fi kún fún ìṣàwárí kọ̀ọ̀kan tí a rí. "chunk" (àìpéye) máa ń fi apá tí ó bá mu wọlé, tó fẹ́rẹ̀ẹ́ tó ọ̀rọ̀ 400. "window" máa ń fi apá náà kún àwọn apá tó yí i ká láti ojú-ìwé kan náà. "page" máa ń fi gbogbo ojú-ìwé módù tí ìbáramu náà wà nínú rẹ̀ kún. window/page ṣe pàtàkì nígbà tí èsì bá gba gbogbo ojú-ìwé kan, ṣùgbọ́n ó máa ń mú kí prompt tóbi jù.';
$string['settings:rag_window_size'] = 'Ìwọ̀n fèrèsé ìwádìí';
$string['settings:rag_window_size_desc'] = 'Fún àyè ìpadàbọ̀ "window": iye àwọn apá tó yí i ká tí ó yẹ kí a fi kún ní ìhà kọ̀ọ̀kan ti apá tí a rí. Àìpéye jẹ́ 1.';
$string['settings:rag_parent_max_chars'] = 'Ààlà ọ̀rọ̀ òbí (àwọn ohun kikọ)';
$string['settings:rag_parent_max_chars_desc'] = 'Iye tó pọ̀ jùlọ ti àwọn ohun kikọ fún ọ̀rọ̀ window/page tí a fẹ̀ sí i. Àwọn ojú-ìwé tí ó kọjá ààlà máa ń padà sí window, lẹ́yìn náà sí apá kan ṣoṣo. Àìpéye jẹ́ 6000.';
$string['settings:rag_enabled'] = 'Mú RAG ṣiṣẹ́ (Ìwádìí Ìtumọ̀)';
$string['settings:rag_enabled_desc'] = 'Nígbà tí a bá mú un ṣiṣẹ́, olùkọ́ AI ń lo ìwádìí ìtumọ̀ láti mú àkóónú kọ́ọ̀sì tí ó bá ìbéèrè kọ̀ọ̀kan mu jáde dípò kí ó kó gbogbo àkóónú sí inú system prompt.';
$string['settings:rag_heading'] = 'RAG / Ìwádìí Ìtumọ̀';
$string['settings:rag_heading_desc'] = 'Retrieval-Augmented Generation: ṣe àtọ́ka àkóónú kọ́ọ̀sì gẹ́gẹ́ bí embedding, kí o sì mú àwọn àjákù tí ó bá a mu jùlọ nìkan jáde ní àkókò ìbéèrè. Ó ń dín lílo token kù ó sì ń ti gbogbo irú àkóónú lẹ́yìn. Ó nílò API embedding.';
