$string['settings:prompt_debug_enabled_desc'] = 'When on, every chat-turn writes the full assembled system prompt and per-section character counts to <code>moodledata/temp/sola_prompt_debug.log</code> (rolling at ~1MB). Default off. Use to measure prompt size empirically and audit which sections contribute the most tokens. The log contains the system prompt only (no learner input or PII).';
$string['settings:socratic_verbose'] = 'Prompt gbòòrò fún ọ̀nà Socratic';
$string['settings:socratic_verbose_desc'] = 'Nígbà tí ó bá tàn, àwọn kọ́ọ̀sì tí ó wà ní ọ̀nà Socratic yóò gba gbogbo ìtọ́ni ṣe/má-ṣe tí ó tó bí i token 600 tí a kọ́kọ́ fi kún un ní v3.9.30. Nígbà tí ó bá pa (àbáwọlé), wọ́n yóò gba ìtọ́ni ìlà-kan tí àwọn àwòṣe òde-òní tí a gbàlejò ń tẹ̀lé dáadáa, èyí sì ń fi bí i token 600 pamọ́ ní ìyípo kọ̀ọ̀kan. Tan èyí bí kọ́ọ̀sì kan bá ń ṣiṣẹ́ lórí àwòṣe tí a gbàlejò fúnra-ẹni tí kò lágbára tí ó nílò ìkọ́lé kedere.';
$string['settings:prompt_budget_chars'] = 'Ìnáwó àwọn lẹ́tà ti system prompt';
$string['settings:prompt_budget_chars_desc'] = 'Maximum total size of the assembled system prompt before the user message, in characters. The structured prompt builder organises sections by category (identity, course context, learner state, behaviour, markers, safety) and drops or truncates the lowest-priority sections when the budget is exceeded. Safety guidance is always preserved in full. Default 8,000 characters (~2,000 tokens). Lower values reduce per-turn cost; higher values allow more course content to land in-prompt.';
$string['settings:current_page_content_maxchars'] = 'Ààlà àkóónú ojú-ìwé lọ́wọ́lọ́wọ́ (àwọn lẹ́tà)';
$string['settings:current_page_content_maxchars_desc'] = 'Iye àwọn lẹ́tà tó pọ̀ jù ti ọ̀rọ̀ ojú-ìwé lọ́wọ́lọ́wọ́ tí a fi sí inú system prompt gẹ́gẹ́ bí abala "Current Page Content", nígbà tí RAG bá wà ní pípa. Àpèjúwe 8,000 ń sọ àwọn ìbéèrè tó dá lórí ojú-ìwé di gbígbọ́ngbọ̀n dáadáa nígbà tí ó fi àyè sílẹ̀ fún ìkọ́lé àti àwọn ìtọ́ni. (Tí RAG bá ṣiṣẹ́, dípò bẹ́ẹ̀ a máa fi àwọn àjákù tó bá àkòrí mu jù ti ojú-ìwé náà gbé e kalẹ̀, pẹ̀lú ìfẹ́ràn ojú-ìwé lọ́wọ́lọ́wọ́, nítorí náà ààlà yìí kì í wúlò.) A máa gé orí ojú-ìwé tó gùn púpọ̀ dé iye àwọn lẹ́tà yìí, nítorí náà a lè má fa ìparí ojú-ìwé tó gùn jọjọ; ṣíṣe RAG máa yẹra fún èyí. Àwọn sàìtì tó kọbi-ara sí iye-owó lè dín kù (fún àpẹẹrẹ 3,000-4,000). A dí i mọ́ àyè 500-8,000. Ó yàtọ̀ sí <code>prompt_budget_chars</code>: èyí ń dí abala ojú-ìwé nìkan mọ́; ìnáwó náà ń dí gbogbo prompt mọ́.';
$string['settings:prompt_verbosity'] = 'Ìgbòòrò prompt';
$string['settings:prompt_verbosity_desc'] = 'Ìgbòòrò àbáwọlé fún àwọn bulọ́kù ìtọ́ni (ọ̀nà Socratic, àwọn ohun èlò òde). Ṣókí (àbáwọlé) ni ohun tí àwọn àwòṣe òde-òní tí a gbàlejò ń tẹ̀lé dáadáa; ìdiwọ̀n ń fi ìkọ́lé kedere kún un fún àwọn àwòṣe ìpele-àárín; gbòòrò ń pa ìtọ́sọ́nà wúwo ti àkókò v3.9.30 mọ́ fún àwọn àwòṣe tí a gbàlejò fúnra-ẹni tí kò lágbára. Ìfàgilé fún kọ́ọ̀sì kọ̀ọ̀kan wà nípasẹ̀ <code>prompt_verbosity_course_&lt;id&gt;</code>.';
