$string['settings:prompt_verbosity_verbose'] = 'Gbòòrò (fún àwọn àwòṣe tí a gbàlejò fúnra-ẹni tí kò lágbára)';
$string['settings:prompt_metrics_enabled'] = 'Gba àwọn òsùwọ̀n prompt fún abala kọ̀ọ̀kan';
$string['settings:prompt_metrics_enabled_desc'] = 'Nígbà tí ó bá tàn (àbáwọlé), gbogbo ìyípo ìjíròrò máa ń kọ ìlà JSON kan fún prompt kọ̀ọ̀kan tí a kójọ sí <code>moodledata/sola_prompt_metrics/YYYY-MM-DD.log</code> pẹ̀lú iye lẹ́tà fún ẹ̀ka kọ̀ọ̀kan. Ọjọ́ 7 tí ó kẹ́yìn ni a ń pamọ́. Ojú-ìwé alákòóso òsùwọ̀n ń kó wọn papọ̀ fún àbá ìnáwó. A kò ń kọ PII kankan sílẹ̀ — ìwọ̀n abala nìkan. Pa á tì bí ilé-ẹ̀kọ́ rẹ bá fẹ́ kí fáìlì òsùwọ̀n má sì rárá.';
$string['settings:prompt_budget_auto_tune'] = 'Ìtúnṣe ìnáwó àṣẹ ètò lójoojúmọ́ fúnra rẹ̀ (a ti kọ̀ sílẹ̀)';
$string['settings:prompt_budget_auto_tune_desc'] = 'A ti kọ̀ sílẹ̀. Kò ṣe ohunkóhun àyàfi bí ipò ìnáwó tí ó wà lókè bá wà ní <strong>Tí a gbé kalẹ̀</strong>. Iṣẹ́ ojoojúmọ́ kan máa ń ṣírò ìnáwó lẹ́tà nípa wíwo gígékúrú àti nípa lílépa àṣẹ tí ó tóbi jù tí ó rí. Rírí ìnáwó láti inú fèrèsé ọ̀rọ̀ àwòṣe ń ṣe é dáadáa jù: kò lè mì, kò sì nílò dátà ìbẹ̀rẹ̀. Àwọn méjèèjì tún ń takò ara wọn, nítorí iṣẹ́ náà ń kọ ìnáwó lẹ́tà, àti pé iye yòówù tí kò jẹ́ àbáyọ máa ń pa ìnáwó tí a rí. Fi í sílẹ̀ ní pípa; a óò yọ ọ́ kúrò ní ìtúsílẹ̀ ọjọ́ iwájú. Ìmọ̀ràn náà ṣì ń hàn lórí ojú-ìwé <a href="/local/ai_course_assistant/prompt_metrics.php">Ìwọ̀n àṣẹ</a>.';
$string['task:auto_tune_prompt_budget'] = 'Ṣàtúnṣe ààlà ìnáwó ìgbékalẹ̀ [[tutorshort]] ní adáṣiṣẹ́ láti inú àwọn ìdíwọ̀n tí a ṣàkíyèsí';
