$string['settings:backend_context_tokens'] = 'Fèrèsé àyíká backend (àwọn token)';
$string['settings:backend_context_tokens_desc'] = 'Gígùn àyíká tó ga jù (max_model_len) ti backend AI rẹ, ní àwọn token. Ṣètò sí 0 fún àwọn àwòṣe tí a gbàlejò pẹ̀lú fèrèsé ńlá (kò sí dídíwọ̀n). Nígbà tí a bá ṣètò ju 0 lọ (fún àpẹẹrẹ 8192 lórí backend vLLM tí a gbàlejò fúnra ẹni), [[tutorshort]] máa ń dín ìnáwó àmì àkọsílẹ̀ ti àṣẹ-ẹ̀rọ kù lókè kí àṣẹ pẹ̀lú àbájáde tí a fi pamọ́ àti ìtàn ìfọ̀rọ̀wérọ̀ lè wọ inú fèrèsé náà, kódà nínú àwọn èdè tí ó kún fún token. Wo ojú ewé wiki Deployment Sizing fún bí èyí ṣe bá àwọn olùmúlò tó wà lẹ́ẹ̀kan náà mu.';
$string['settings:backend_retry_attempts'] = 'Àwọn ìgbìyànjú àtúnṣe backend';
$string['settings:backend_retry_attempts_desc'] = 'Iye ìgbà tí a ó tún gbìyànjú àṣìṣe backend ìgbà díẹ̀ (HTTP 429 tàbí 503) kí a tó fi àṣìṣe hàn akẹ́kọ̀ọ́. Àwọn àtúnṣe máa ń ṣẹlẹ̀ kìkì kí ọ̀rọ̀ ìdáhùn èyíkéyìí tó bẹ̀rẹ̀ sí ṣàn, nítorí náà àbájáde kò ní ṣẹ̀ ẹ̀ẹ̀mejì. A pète rẹ̀ sí àwọn backend kéékèèké tí a gbàlejò fúnra ẹni tí ń kọ àwọn ìbéèrè nígbà ẹrù pọ̀. Ṣètò sí 0 láti pa á. Àpèjúwe 2.';
$string['settings:backend_retry_max_wait'] = 'Àkókò ìdúró tó ga jù fún àtúnṣe backend (àwọn ìṣẹ́jú-àáyá)';
$string['settings:backend_retry_max_wait_desc'] = 'Ààlà òkè, ní àwọn ìṣẹ́jú-àáyá, lórí bí a ṣe pẹ́ tó láti bọ̀wọ̀ fún àkọlé Retry-After láti ọ̀dọ̀ backend kí a tó tún gbìyànjú. Nígbà tí backend kò bá fi Retry-After ránṣẹ́, [[tutorshort]] máa ń lo backoff exponential kúkúrú dípò. Àpèjúwe 5.';
$string['prompt:truncation_hint'] = 'ÀKÍYÈSÍ: A kò lè wá inú gbogbo àkóónú ẹ̀kọ́ ní àyípadà yìí nítorí àwọn ààlà gígùn. Bí akẹ́kọ̀ọ́ bá béèrè nípa ohun kan tí o kò lè rí nínú àkóónú tí a pèsè, sọ pé o kò lè wá gbogbo ẹ̀kọ́ náà kí o sì dámọ̀ràn kí wọ́n ṣí ojú ewé tàbí iṣẹ́ pàtó níbi tí a ti sọ̀rọ̀ kókó náà, dípò sísọ pé kò sí nínú ẹ̀kọ́ náà.';
