$string['settings:rag_currentpage_boost_desc'] = 'Èrè kékeré kan tí a fi kún ìwọ̀n ìbáramu àwọn àjákù láti ojú-ìwé tí akẹ́kọ̀ọ́ ń wò lọ́wọ́lọ́wọ́, kí àwọn ìbéèrè bíi "ṣàlàyé èyí" lè fẹ́ràn ojú-ìwé tí ó hàn nígbà tí àwọn ìwọ̀n bá súnmọ́ ara wọn. Ìṣètò nìkan: kì í fi agbára mú àjákù ojú-ìwé tí kò bá àkòrí mu kọjá ẹnu-ọ̀nà ìbáramu tó kéré jù. Ṣètò sí 0 láti pa á.';
$string['settings:history_mode'] = 'Ọ̀nà Ìyàn Ìtàn';
$string['settings:history_mode_desc'] = 'Bí a ṣe ń yan àwọn ìpadé ìjíròrò tó kọjá kí a tó fi wọ́n ránṣẹ́ sí àwòṣe náà. <strong>Semantic</strong> máa pa àwọn ìpadé àìpẹ́ tí ó bá ìbéèrè lọ́wọ́lọ́wọ́ mu mọ́ nìkan (àti ìpàrọ̀ tó ṣẹ̀ṣẹ̀ jù nígbà gbogbo), kí ìpadé àtijọ́ tó kúrò ní àkòrí má bàa mú iye-owó pọ̀ sí i tàbí kó fa ìdáhùn kúrò ní ọ̀nà; ó máa ń ṣe ìpè embedding kan ní àfikún fún ìfọ̀rọ̀wérọ̀ kọ̀ọ̀kan. <strong>Recency</strong> máa pa àwọn bata "Max Conversation History" tó kẹ́yìn mọ́ láìka ìbáramu sí (ìhùwàsí tó ti pẹ́, kò sí ìpè àfikún). Bí embedding kò bá sí, ọ̀nà semantic máa padà sí recency fúnra rẹ̀.';
$string['settings:history_mode_semantic'] = 'Semantic (àwọn ìpadé àìpẹ́ tó bá àkòrí mu)';
$string['settings:history_mode_recency'] = 'Recency (bata N tó kẹ́yìn)';
$string['settings:history_semantic_minscore'] = 'Ìpẹ̀lẹ̀ Ìbáramu Ìtàn (cosine)';
$string['settings:history_semantic_minscore_desc'] = 'Nínú ọ̀nà ìtàn semantic, a máa pa ìpadé tó kọjá mọ́ kìkì bí ìbáramu rẹ̀ sí ìbéèrè lọ́wọ́lọ́wọ́ bá kéré jù iye yìí lọ (a máa pa ìpàrọ̀ tó ṣẹ̀ṣẹ̀ jù mọ́ nígbà gbogbo). Àyè 0 sí 1; ó dá lórí àwòṣe. Gbé e ga kí ó le mọ́ (ìtàn tó kéré), sọ̀ ọ́ kalẹ̀ láti pa púpọ̀ mọ́.';
$string['settings:history_candidates'] = 'Fèrèsé Olùdíje Ìtàn';
$string['settings:history_candidates_desc'] = 'Nínú ọ̀nà ìtàn semantic, kìkì iye bata àìpẹ́ yìí ni a ń fún ní ìwọ̀n fún ìbáramu (ààlà iye-owó). A kì í fi àwọn bata tó dàgbà ju fèrèsé yìí ránṣẹ́. Pa á mọ́ ní ìwọ̀n tàbí ó ga ju "Max Conversation History" lọ.';

// v5.11.0 - v6.2.0 strings (added 2026-06-10).
$string['settings:embed_provider_voyage'] = 'Voyage AI (voyage-3.5 — a dámọ̀ràn; +4 MTEB bí ó ṣe wé mọ̀ OpenAI 3-small, 4x context, ọ̀pọ̀lọpọ̀ èdè)';
$string['settings:rerank_heading'] = 'RAG: Àgbéjáde ìpele méjì (re-ranking)';
$string['settings:rerank_heading_desc'] = 'Ìpele àgbéjáde ìkeji tí kò jẹ́ dandan: cosine similarity fìdí N-chunk olùdíje olókùúta (àpèjúwe 50), lẹ́yìn náà cross-encoder re-ranker gbé iye (ìbéèrè, chunk) ìtọ́jú kọ̀ọ̀kan, àwọn K-olókùúta tó dára jù wọ inú prompt. Ó pa dà nígbà àpèjúwe; bí re-ranker kò bá ṣètò rẹ̀ tàbí bá kùnà cosine ìpele kan máa ń yára padà.';
$string['settings:rerank_enabled'] = 'Àgbéjáde ìpele méjì (Voyage rerank-2.5)';
$string['settings:rerank_enabled_desc'] = 'Nígbà tí ó bá ṣiṣẹ́, àgbéjáde RAG di ìpele méjì: cosine similarity padà pẹ̀lú olùdíje N-olókùúta (àpèjúwe 50), lẹ́yìn náà Voyage rerank-2.5 cross-encoder gbé iye kọ̀ọ̀kan àti K-olókùúta wọ inú prompt. Àwọn ìlọsíwájú tí a tẹ̀jáde: +15 Recall@10 ilé-iṣẹ́, +39% NDCG BEIR. ~$0.05/MTok ìsan-owó. Nílò <code>rerank_apikey</code> ní ìsàlẹ̀; bí rerank kò bá sí tàbí kùnà cosine ìpele kan máa ń yára padà.';
$string['settings:rerank_apikey'] = 'Rerank API key';
$string['settings:rerank_apikey_desc'] = 'Voyage AI API key fún rerank-2.5. Fi sílẹ̀ ní ofo láti tún lo Embedding API Key ní ìsàlẹ̀ (àwọn ìfìjíṣẹ́ Voyage tí ó wọ́pọ̀ pín key kan fún embed + rerank).';
$string['settings:rerank_model'] = 'Rerank model';
$string['settings:rerank_model_desc'] = 'Àpèjúwe <code>rerank-2.5</code>. Àwọn awoṣe Voyage rerank tuntun lè jẹ́ sísọ níbí.';
$string['settings:rerank_apibaseurl'] = 'Rerank API base URL';
$string['settings:rerank_apibaseurl_desc'] = 'Bori Voyage rerank base URL. Fi sílẹ̀ ní ofo láti lo Embedding API Base URL ní ìsàlẹ̀, tàbí Voyage àpèjúwe (<code>https://api.voyageai.com/v1</code>).';
$string['settings:rerank_candidates'] = 'Rerank candidate window';
$string['settings:rerank_candidates_desc'] = 'Iye olùdíje cosine top-N tí ó ń wọ ìpele ìtúnṣe ipò. Àsàyàn 20. A díwọ̀n rẹ̀ lórí ìbéèrè 1,008: 20 bá 30 mu ní recall (R@3 89.0% sí 89.3%) pẹ̀lú ìdíyelé tí ó dínkù ní ìdá kan nínú mẹ́ta, nígbà tí 50 ná ìlọ́po 2.5 láìsí èrè tí a lè díwọ̀n. Ní ìsàlẹ̀ 10, recall ń dínkù. Ìdíyelé ń pọ̀ sí i ní ìlà tààrà pẹ̀lú iye yìí.';
$string['settings:stt_selfhosted_heading'] = 'Ìgbasilẹ̀ ohùn tí a gbàlejò fúnra ẹni (Whisper)';
$string['settings:stt_selfhosted_heading_desc'] = 'Ṣe speech-to-text lórí ohun èlò tìẹ ní iye ọ̀fọ̀ ọ̀fẹ́ fún ìdákẹjẹ́. Tọ [[tutorshort]] sí sọ́fítiwéàrì ìgbasilẹ̀ eyíkéyìí tó bá mu OpenAI: <code>whisper-server</code> Docker, <code>speaches</code> (faster-whisper), tàbí <code>whisper.cpp</code> server. Nígbà tí a bá ṣètò server URL níbí ó di ọ̀nà STT àpèjúwe; yan olùpèsè tó san owó nínú Olùpèsè STT tí ó ṣiṣẹ́ ní ìsàlẹ̀ láti bori. Bí server bá wà lórí nẹ́tíwọ́kì àdáni tàbí plain http, tún fi host rẹ̀ kun sínú atẹ̀jẹ́ SSRF trusted endpoints nínú apá Ààbò.';
$string['settings:stt_selfhosted_url'] = 'Selfhosted STT server URL';
$string['settings:stt_selfhosted_url_desc'] = 'Base URL ti server ìgbasilẹ̀ tó bá mu OpenAI, fún àpẹẹrẹ <code>http://10.0.0.5:8000</code>. [[tutorshort]] fi <code>/v1/audio/transcriptions</code> kún fúnra rẹ̀; ọ̀nà endpoint tán tún gba. Fi sílẹ̀ ní ofo láti pa selfhosted STT.';
$string['settings:stt_selfhosted_model'] = 'Selfhosted STT model';
$string['settings:stt_selfhosted_model_desc'] = 'Orúkọ awoṣe tí a rán sí server, tó bá Whisper model tí ó ṣe gbé depo — fún àpẹẹrẹ <code>Systran/faster-whisper-small</code> fún speaches tàbí <code>large-v3</code>. Fi sílẹ̀ ní ofo láti rán <code>whisper-1</code>, eyí tí ọ̀pọ̀lọpọ̀ àwọn selfhosted server gba tàbí fojú kójú.';
$string['settings:stt_selfhosted_apikey'] = 'Selfhosted STT API key';
$string['settings:stt_selfhosted_apikey_desc'] = 'Àṣeyẹlẹ̀. Ọ̀pọ̀lọpọ̀ àwọn selfhosted server jẹ́ key-less lẹ́yìn nẹ́tíwọ́kì tí a gbẹ́kẹ̀lé; ṣètò èyí kìkì bí server rẹ bá nílò bearer token.';
