$string['settings:prompt_proportions_heading'] = 'Àwọn ìpín apá prompt (v5.6.0)';
$string['settings:prompt_proportions_heading_desc'] = 'Pín àwọn àwárí ìpín system prompt sí àwọn bọ́ọ̀kẹ̀ mẹ́rin: ààbò + ìdámọ̀, ìgbékalẹ̀ ẹ̀kọ́, àkóónú ẹ̀kọ́, àti ojú ewé lọ́wọ́lọ́wọ́. Àwọn ìwọ̀n jẹ́ ìpínfà tí ó fi kún 100. Àwọn àpèjúwe tí a ṣe atunṣe nipa iriri (10 / 10 / 40 / 40) wá láti àwọn àwárí ìwọ̀n v5.6.0; fífi textarea sílẹ̀ ní ofo máa ń lo àwọn àpèjúwe wọnnì. Ìgbéga aifọwọ́ṣe ṣe àtúnṣe ìpín fún ìyípadà kọ̀ọ̀kan tí ó da lórí bóyá ojú ewé pàtó kan wà nínú àwárí.';
$string['settings:prompt_section_weights'] = 'Àwọn ìwọ̀n apá ìpìlẹ̀ (JSON)';
$string['settings:prompt_section_weights_desc'] = 'JSON object àṣeyẹlẹ̀ tí ó ṣe maapu bọ́ọ̀kẹ̀ kọ̀ọ̀kan sí ìpínfà. Fi sílẹ̀ ní ofo láti lo àwọn àpèjúwe tí a ṣe àwárí (10 / 10 / 40 / 40). Àpẹẹrẹ: <code>{"safety_identity": 10, "course_structure": 10, "course_content": 40, "current_page": 40}</code>. Àwọn ìwọ̀n gbọ́dọ̀ fi kún 100 (±5%). <code>safety_identity</code> ní ilẹ̀ 10%. <code>current_page + course_content</code> gbọ́dọ̀ jẹ́ 40% àt àpẹẹrẹ. Àwọn iye tí ó jáde lọ sínú àwọn àpèjúwe àwárí padà.';
$string['settings:prompt_context_boost_mode'] = 'Ọ̀nà context boost';
$string['settings:prompt_context_boost_mode_desc'] = 'Àtúnṣe aifọwọ́ṣe tí ó yí ìwọ̀n sọdọ apá ojú ewé lọ́wọ́lọ́wọ́ nígbà tí ojú ewé pàtó wà nínú àwárí. <strong>page_focus</strong> (àpèjúwe) yí ìwọ̀n ìpín 15 nǹkan. <strong>aggressive</strong> yí ìpín 25 tó dára nígbà tí akẹ́kọ̀ọ́ sábà máa ń béèrè ìbéèrè pàtó ojú ewé. <strong>off</strong> pa boost; àwọn ìwọ̀n ìpìlẹ̀ tí alábòójútó ṣètò wà ní ipa fún ìyípadà gbogbo.';
