$string['settings:prompt_context_boost_aggressive'] = 'Aggressive (~yíyí ìpín 25)';
$string['settings:prompt_section_weights_coach'] = 'Coach-mode override (JSON, àṣeyẹlẹ̀)';
$string['settings:prompt_section_weights_coach_desc'] = 'JSON object àṣeyẹlẹ̀ tí ó bori àwọn ìwọ̀n apá ìpìlẹ̀ pàtó nígbà ọ̀nà coach quizzi tí a gba àmì (<code>quizmode=coach</code>). Wúlò láti fi agbara ìpín <code>current_page</code> tó wúwo nígbà àwọn quizzi láìka ipa si chat déédéé. Fi sílẹ̀ ní ofo láti gba àwọn ìwọ̀n ìpìlẹ̀.';
$string['prompt_debug_view:title'] = 'Olùwò àkọsílẹ̀ debug prompt';
$string['prompt_debug_view:subtitle'] = 'System prompt tí a kó jọ + ìpín fún ìpín kọ̀ọ̀kan + ìtàn ìfọ̀rọ̀wérọ̀ + ìfiránṣẹ́ olùmúlò lọ́wọ́lọ́wọ́ + metadata asopọmọra, gẹ́gẹ́ bí awoṣe ti gba wọn. Lo èyí láti ṣe àmójútó bóyá apá bí Àkóónú Ojú Ewé Lọ́wọ́lọ́wọ́ ṣe gba sínú prompt àti láti ṣe àwárí ìṣòro ìdára ìdáhùn láì SSH sínú server.';
$string['prompt_debug_view:disabled'] = 'Àkọsílẹ̀ debug prompt jẹ́ TÍ A PA lọ́wọ́lọ́wọ́. Kò sí àkọ tuntun tí yóò kọ títí tí a ó fi mú un ṣiṣẹ́.';
