$string['settings:mastery_classifier_provider'] = 'Olùpèsè classifier';
$string['settings:mastery_classifier_provider_desc'] = 'Id olùpèsè tí a lò fún mastery classifier ìyípadà kọ̀ọ̀kan. Fi sílẹ̀ ní ofo láti gba olùpèsè AI àpèjúwe. Àpèjúwe <code>openai</code> pọ̀ pẹ̀lú awoṣe classifier <code>gpt-4o-mini</code> ní ìsàlẹ̀ — àṣeyẹlẹ̀ TIER 1 tó tẹ́lẹ̀ fún ìpín tó ní ìtọ́sọ̀nà-àgbékalẹ̀ (~ìfowopamọ́ $220/osù ni 100k MAU bí a ṣe wé pẹ̀lú chat tier). Nígbà tí a bá ṣètò, ìlà nínú Àwọn olùpèsè ìfiwéra pẹ̀lú id olùpèsè yìí pèsè API key, base URL, àti temperature.';
$string['settings:premium_escalation_heading'] = 'Ìpele ìgbéga premium (A.10)';
$string['settings:premium_escalation_heading_desc'] = 'Yíyípadà ìyípadà kọ̀ọ̀kan sí awoṣe premium (Claude Opus 4.8 nígbà àpèjúwe) fún àwọn ìbéèrè níbi tí ìpele chat workhorse ń ṣe aáforíjì pẹ̀lú — ní àpẹẹrẹ math ìpele-méjì, CS, àti ìrọ̀rùn sáyẹ̀nsì. A yanjú rẹ̀ nípasẹ̀ àwárí A.10 2026-06-09: Opus 4.8 bori ni 14.97/15 bí ó ṣe wé mọ̀ gpt-4o ní 12.68/15 lórí àwọn prompt tó ṣòro. Àwọn ọ̀nà trigger méjì: àwọn regex tó bá ìfiránṣẹ́ olùmúlò mu, TÀBÍ atẹ̀jẹ́ ẹ̀kọ́ tó gbé gbogbo ìyípadà. Pa nígbà àpèjúwe. Ni ~5% ìgbéga, retí ~$700/osù ni 100k [[unishort]] MAU lórí ìnáwó chat ìpìlẹ̀.';
$string['settings:premium_escalation_enabled'] = 'Mú yíyípadà ìgbéga premium ṣiṣẹ́';
$string['settings:premium_escalation_enabled_desc'] = 'Nígbà tí ó bá ṣiṣẹ́, router ìyípadà kọ̀ọ̀kan ṣàyẹ̀wò àkójọ trigger regex àti atẹ̀jẹ́ ẹ̀kọ́ fún ìpè chat kọ̀ọ̀kan; àwọn ìyípadà tó bá mu wọ inú olùpèsè premium. Padà sí olùpèsè workhorse bí ìlà premium bá ṣegbé tàbí kùnà láti ṣẹdá.';
$string['settings:premium_escalation_provider'] = 'Olùpèsè premium';
$string['settings:premium_escalation_provider_desc'] = 'Id olùpèsè láti darí àwọn ìpè premium nípasẹ̀. Gbọ́dọ̀ bá ìlà nínú Àwọn olùpèsè ìfiwéra mu. Àpèjúwe <code>claude</code>.';
$string['settings:premium_escalation_model'] = 'Awoṣe premium';
$string['settings:premium_escalation_model_desc'] = 'Orúkọ awoṣe tí a rán sí olùpèsè premium. Àpèjúwe <code>claude-sonnet-5</code> gẹ́gẹ́ bí ìdájọ́ àwárí A.10.';
$string['settings:premium_escalation_triggers'] = 'Àwọn trigger regex premium';
$string['settings:premium_escalation_triggers_desc'] = 'Ọ̀kan PCRE regex fún ìlà kọ̀ọ̀kan (láì sí delimiter; bíbo case-insensitive wà ni ara rẹ̀ aifọwọ́ṣe). Àwọn ìlà tí ó bẹ̀rẹ̀ pẹ̀lú # jẹ́ àkọsílẹ̀. Fi sílẹ̀ ní ofo láti lo àkójọ àpèjúwe tí a ṣetọ́jú láti àwárí A.10 (àwọn ami STEM ìpele-méjì: "derive", "prove that", "step by step", LaTeX math, fenced code blocks, big-O, integrals, optimization, àti bẹ́ẹ̀ bẹ́ẹ̀ lọ).';
$string['settings:premium_escalation_course_tags'] = 'Atẹ̀jẹ́ ẹ̀kọ́ premium';
$string['settings:premium_escalation_course_tags_desc'] = 'Ọ̀kan shortname ẹ̀kọ́ tàbí prefix idnumber fún ìlà kọ̀ọ̀kan. Gbogbo ìyípadà nínú ẹ̀kọ́ tó bá mu auto-escalates láì gbé regex ìfiránṣẹ́ kalẹ̀ (lo fún àwọn ẹ̀kọ́ STEM tó pọ̀ níbi tí ìgbéga yẹ kí ó jẹ́ àpèjúwe). Bíbo jẹ́ prefix case-insensitive — "MATH" bá MATH121, MATH205, àti bẹ́ẹ̀ bẹ́ẹ̀ lọ mu.';
$string['settings:spend_cap_per_course_default'] = 'Ìdiwọ̀n ìnáwó ẹ̀kọ́-kọ̀ọ̀kan àpèjúwe (USD)';
$string['settings:spend_cap_per_course_default_desc'] = 'Ìdiwọ̀n ìdáàbòbò tí a lò fún ẹ̀kọ́ gbogbo tí kò ní ìdiwọ̀n ìnáwó ẹ̀kọ́-kọ̀ọ̀kan tirẹ̀. Ṣètò sí e.g. <code>30</code> láti di ìnáwó osùnmìgbà ẹ̀kọ́ kanná mọ́ ní $30 láì ṣe atunṣe àwọn ẹ̀kọ́ kọ̀ọ̀kan. <code>0</code> = kò sí àpèjúwe. Nígbà tí ẹ̀kọ́ ba rekọjá 80% / 95% / 100% ti ìdiwọ̀n yìí, àkọọ́sọ alábòójútó tó wà tẹ́lẹ̀ ti spend-guard máa ń rán ìfiránṣẹ́ alábòójútó (àkójọ olùgba: <code>spend_notify_emails</code>).';
$string['settings:cost_anomaly_heading'] = 'Àwárí àmì iye tí kò dára (v6.0)';
$string['settings:cost_anomaly_heading_desc'] = 'Iṣẹ́ tí a ṣètò ojoojúmọ́ (<code>cost_anomaly_check</code>) tí ó fi ìnáwó [[tutorshort]] ojú ìwé lónìí ṣe ìfiwéra pẹ̀lú ìgbà-àárín rolling ọjọ́ 7. Máa ń fi ímeèlì ránṣẹ́ sí àkójọ olùgba <code>spend_notify_emails</code> nígbà tí lónìí bá rekọjá multiplier tí a ṣètò × ìgbà-àárín. Mú àwọn ìṣòro mẹ́ta tí àwọn ìwọ̀n 80% / 95% / 100% spend-cap tẹ́lẹ̀ ò gba: (1) ẹ̀kọ́ tí ń sáré, (2) jíjẹ́ kí ìpele premium ṣiṣẹ́ láìmọ̀, (3) misroute olùpèsè. Pa nígbà àpèjúwe.';
$string['settings:cost_anomaly_enabled'] = 'Mú àwárí àmì iye tí kò dára ṣiṣẹ́';
$string['settings:cost_anomaly_enabled_desc'] = 'Nígbà tí ó bá ṣiṣẹ́, iṣẹ́ tí a ṣètò ojoojúmọ́ ṣe àyẹ̀wò ìnáwó lónìí pẹ̀lú ìgbà-àárín rolling ọjọ́ 7 àti fi ímeèlì ránṣẹ́ sí àwọn alábòójútó lórí àmì àìdára. Àwọn ọjọ́ 7 àkọ́kọ́ lẹ́yìn jíjẹ́ kó ṣiṣẹ́ máa ń fi ipò <code>insufficient_history</code> hàn àti kò fi ìkìlọ̀ ránṣẹ́. Idempotent fún ọjọ́ kọ̀ọ̀kan.';
$string['settings:cost_anomaly_multiplier'] = 'Multiplier àmì àìdára';
$string['settings:cost_anomaly_multiplier_desc'] = 'Ìnáwó lónìí gbọ́dọ̀ rekọjá multiplier yìí × ìgbà-àárín ọjọ́ 7 láti mú ìkìlọ̀ ṣiṣẹ́. Àpèjúwe <code>2.0</code>. Dín kù sí <code>1.5</code> fún àwọn ìkìlọ̀ títọ̀wọ́n sáaju. Gbé sí <code>3.0</code> bí ìlò [[unishort]] bá jẹ́ pé àwọn spikes 2x jẹ́ déédéé.';
$string['task:cost_anomaly_check'] = '[[tutorshort]] àyẹ̀wò àmì iye tí kò dára (ojoojúmọ́)';

// v6.4.0 signed policy bundle strings (added 2026-06-11).
$string['settings:policy_bundle_heading'] = 'Policy bundle tí a fọwọ́ sí (àwọn ìmúdójúìwọ̀n ìhùwàsí jíjìn)';
$string['settings:policy_bundle_heading_desc'] = 'Ló àwọn ìtọ́sọ́nà ìhùwàsí (àwọn prompt, routing, àwọn okunfa escalation, ìtọ̀nà RAG, ìlànà ìnáwó) láti ọ̀dọ̀ fáìlì JSON tí a fọwọ́ sí àkọóbẹ̀rẹ̀ láì fi ìpínlẹ̀ kóòdù tì. Iṣẹ́ tí a ṣètò ojoojúmọ́ máa ń gbà URL bundle, máa ń ṣe ìmúdájú fọwọ́ Ed25519 rẹ̀ lòdì sí ìpìlẹ̀ gbangba tó wà nísàlẹ̀, ó sì máa ń lo àwọn ìtọ́sọ́nà nìkan bí gbogbo kọkọrọ bá wà nínú allowlist tí a gbé kalẹ̀ àti bí ẹ̀yà bundle bá jẹ́ tuntun ju ẹ̀yà tó gbẹ̀yìn tí a lò. Àwọn kọkọrọ API, URL, webhook, àti àwọn ìtọ́sọ́nà ààbò kò lè ṣeéṣe fún bundle láti fi ìtọ́sọ́nà wọn. Ṣẹ̀dá àti fọwọ́ sí àwọn bundle pẹ̀lú <code>admin/cli/policy_bundle_tool.php</code> (keygen, sign, verify, status, sync).';
$string['settings:policy_bundle_enabled'] = 'Mú policy bundle sync ṣiṣẹ́';
