$string['settings:claude_temperature_allow_prefixes'] = 'Àwọn àwòṣe Claude tí ó gba àtòjọ temperature';
$string['settings:claude_temperature_allow_prefixes_desc'] = 'Ìbẹ̀rẹ̀ orúkọ àwòṣe kan ní ìlà kọ̀ọ̀kan. Àwọn àwòṣe Anthropic tí orúkọ wọn bẹ̀rẹ̀ pẹ̀lú ọ̀kan nínú ìwọ̀nyí ṣì ń gba àtòjọ ìṣàyẹ̀wò <code>temperature</code>. Fún àwòṣe Claude kankan tí kò bá ìbẹ̀rẹ̀ kankan mu, a fi temperature sílẹ̀ (àwọn àwòṣe ìrònú láti Opus 4.7 lọ ń kọ̀ ọ́ pẹ̀lú àṣìṣe HTTP 400). Fi sílẹ̀ ní òfìfo láti lo iye àbáyanjẹ tí ó wá pẹ̀lú àfikún náà.';
$string['settings:max_tokens'] = 'Ìgùn ìdáhùn tí ó pọ̀ jùlọ (tokens)';
$string['settings:max_tokens_desc'] = 'Iye tokens tí ó pọ̀ jùlọ fún ìdáhùn AI kọ̀ọ̀kan. Iye kékeré ń fún ní ìdáhùn kúkúrú àti kíákíá. 512 = ó tó gbólóhùn 2-3, 1024 = ó tó ìpínrọ̀ 1-2, 2048 = àlàyé gígùn. Fi 0 sí i láti má ní ààlà (iye àbáyanjẹ olùpèsè ni yóò ṣiṣẹ́).';
$string['settings:profile_update_interval'] = 'Àsìkò ìmúdójúìwọ̀n àkọọ́lẹ̀ akẹ́kọ̀ọ́';
$string['settings:profile_update_interval_desc'] = 'Lẹ́yìn iye ìránṣẹ́ yìí láti ọwọ́ akẹ́kọ̀ọ́ nínú ìdálẹ́kọ̀ọ́, olùrànlọ́wọ́ ń kọ (tàbí sọ di tuntun) àkọọ́lẹ̀ ìkẹ́kọ̀ọ́ tí ó ṣàkópọ̀ agbára, àìlera, ọ̀nà ìkẹ́kọ̀ọ́, àti ìfẹ́. A fi àkọọ́lẹ̀ yìí sínú àṣẹ ẹ̀rọ fún ìdáhùn tí ó bá ẹni mu. Fi 0 sí i láti pa á. Àbáyanjẹ: 10.';
$string['settings:enable_thinking'] = 'Ìrònú tí a gbòòrò (Claude nìkan)';
$string['settings:enable_thinking_desc'] = 'Ó ń ṣí ìrònú tí ó ń bá ara mu fún àwọn àwòṣe Claude. Claude fúnra rẹ̀ ni ó ń pinnu ìgbà àti ìwọ̀n tí yóò ronú lórí ìṣòro kí ó tó dáhùn. Ó mú ìpéye dára sí i nínú àwọn ìbéèrè tí ó díjú, ṣùgbọ́n ó ń pọ̀ sí i lílo tokens àti ìdádúró. A kò fi ohun tí ó wà nínú ìrònú hàn àwọn akẹ́kọ̀ọ́. Àwọn olùpèsè mìíràn kò kọbi ara sí ìṣètò yìí.';
$string['settings:rag_sources_heading'] = 'Àwọn orísun àkóónú RAG';
$string['settings:rag_sources_heading_desc'] = 'Yan irú àkóónú ìdálẹ́kọ̀ọ́ tí olùtọ́jú àkọsílẹ̀ RAG yóò yọ ọ̀rọ̀ láti inú rẹ̀. Àwọn àmì ipò lórí <a href="{$a}">ojú ìwé ìṣàkóso RAG</a> ń fi hàn bóyá olùyọ kọ̀ọ̀kan ní ohun tí ó nílò láti ṣiṣẹ́ (bí àpẹẹrẹ ohun èlò pdftotext tàbí àkọsílẹ̀ ìyọ̀ǹda Cloudflare).';
$string['settings:rag_extract_pdf'] = 'Tọ́jú àwọn fáìlì PDF (mod_resource)';
$string['settings:rag_extract_pdf_desc'] = 'Ó ń yọ ọ̀rọ̀ láti inú àwọn fáìlì PDF tí a gbé sókè nípasẹ̀ ohun èlò <code>pdftotext</code> (poppler). A rí ọ̀nà ohun èlò náà láìfọwọ́yí; tọ́ka sí i nísàlẹ̀ bí ó bá pọn dandan.';
$string['settings:rag_pdftotext_path'] = 'Ọ̀nà ohun èlò pdftotext';
$string['settings:rag_pdftotext_path_desc'] = 'Fi sílẹ̀ ní òfìfo fún ìwádìí láìfọwọ́yí (a ń yẹ̀ <code>/usr/bin/pdftotext</code>, <code>/usr/local/bin/pdftotext</code> àti <code>which pdftotext</code> wò). Kún un kìkì bí ìfisọ́wọ́ rẹ bá wà ní ibòmíràn.';
$string['settings:rag_extract_docx'] = 'Tọ́jú àwọn fáìlì DOCX (mod_resource)';
$string['settings:rag_extract_docx_desc'] = 'Ó ń yọ ọ̀rọ̀ láti inú àwọn àkọsílẹ̀ Word tí a gbé sókè nípasẹ̀ ZipArchive PHP. Kò nílò ohunkóhun láti òde.';
$string['settings:rag_extract_pptx'] = 'Tọ́jú àwọn fáìlì PPTX (mod_resource)';
$string['settings:rag_extract_pptx_desc'] = 'Ó ń yọ ọ̀rọ̀ láti inú àwọn àfihàn PowerPoint òde òní tí a gbé sókè nípasẹ̀ ZipArchive PHP. Ó ń rìn kiri XML àwọn ìfaworán àti àkọsílẹ̀ olùsọ̀rọ̀ ní ètò ìfaworán; kò nílò ohunkóhun láti òde. A kò gba àwọn fáìlì binary <code>.ppt</code> àtijọ́ — tún àwọn àfihàn wọ̀nyẹn pamọ́ gẹ́gẹ́ bí <code>.pptx</code>.';
$string['settings:rag_extract_h5p'] = 'Tọ́jú àkóónú H5P (mod_h5p)';
$string['settings:rag_extract_h5p_desc'] = 'Ó ń rìn kiri JSON àkóónú H5P kí ó tọ́jú gbogbo pápá tí ó ní ọ̀rọ̀ (ìbéèrè, ìdáhùn, èsì, àlàyé). Àkọsílẹ̀ àfikún ti irú àkóónú H5P gbòòrò; nínú àwọn ọ̀rọ̀ ààlà, a lè rí àwọn ìbámu àṣìṣe díẹ̀.';
$string['settings:rag_extract_scorm'] = 'Tọ́jú àwọn ìdìpọ̀ SCORM (mod_scorm)';
$string['settings:rag_extract_scorm_desc'] = 'Ó ń tú àwọn ìdìpọ̀ SCORM kí ó tọ́jú <code>imsmanifest.xml</code>, gbogbo fáìlì <code>.html</code>, àti àwọn ọ̀rọ̀ àkóónú Articulate Storyline. <strong>A pa á ní àbáyanjẹ</strong>, nítorí ṣíṣe SCORM lè jẹ́ olówó gọbọi. <code>rag_scorm_max_mb</code> ni ó ń pinnu ìwọ̀n ìdìpọ̀ tí ó pọ̀ jùlọ.';
$string['settings:rag_scorm_max_mb'] = 'Ìwọ̀n ìdìpọ̀ SCORM tí ó pọ̀ jùlọ láti tọ́jú (MB)';
$string['settings:rag_scorm_max_mb_desc'] = 'Ó ń fo àwọn ìdìpọ̀ SCORM tí ó tóbi ju iye yìí lọ láti yàgò fún lílo ìrántí púpọ̀.';
$string['settings:rag_fetch_transcripts'] = 'Gbé àwọn àkọsílẹ̀ ọ̀rọ̀ wá fún fídíò àti àkóónú ìbáṣepọ̀ tí a fi sínú';
$string['settings:rag_fetch_transcripts_desc'] = 'Ó ń yẹ àkóónú mod_page àti mod_book wò fún àwọn iframe tí a fi sínú (Synthesia, YouTube, Articulate, Genially) kí ó gbé àdírẹ́sì àkọsílẹ̀ ọ̀rọ̀ tí ó bá ìfisínú kọ̀ọ̀kan wá (ó ń wá lókè àti nísàlẹ̀ férémù náà). Ó nílò ìsopọ̀ HTTPS tí ó ń jáde láti orí ẹ̀rọ ìsìn yìí sí olùgbàlejò àwọn àkọsílẹ̀ ọ̀rọ̀. <strong>A pa á ní àbáyanjẹ</strong>; ṣí i lẹ́yìn tí olùpèsè àkọsílẹ̀ ọ̀rọ̀ ti fi ẹ̀rọ ìsìn yìí sínú àkọsílẹ̀ ìyọ̀ǹda rẹ̀ (bí àpẹẹrẹ nípasẹ̀ òfin Cloudflare tí ó dá lórí IP).';
$string['settings:rag_iframe_host_patterns'] = 'Àwọn àpẹẹrẹ olùgbàlejò iframe';
$string['settings:rag_iframe_host_patterns_desc'] = 'Ọ̀rọ̀ àṣàyàn déédéé kan ní ìlà kọ̀ọ̀kan, tí a fi bá àbùdá <code>src</code> ti iframe mu. A kà férémù kọ̀ọ̀kan tí ó bá mu sí ìfisínú ìbáṣepọ̀ tí a gbọdọ̀ so àkọsílẹ̀ ọ̀rọ̀ rẹ̀ pọ̀ kí a tọ́jú u. Àwọn ìlà tí ó bẹ̀rẹ̀ pẹ̀lú <code>#</code> jẹ́ àlàyé.';
$string['settings:rag_transcript_url_pattern'] = 'Àpẹẹrẹ àdírẹ́sì àkọsílẹ̀ ọ̀rọ̀';
$string['settings:rag_transcript_url_pattern_desc'] = 'Ọ̀rọ̀ àṣàyàn déédéé tí ó bá àdírẹ́sì àwọn ìjápọ̀ àkọsílẹ̀ ọ̀rọ̀ mu. Fún iframe kọ̀ọ̀kan tí a rí, olùtọ́jú àkọsílẹ̀ ń yan ìjápọ̀ tí ó bá mu tí ó sún mọ́ jùlọ (lókè tàbí nísàlẹ̀ rẹ̀) kí ó so àwọn méjèèjì pọ̀. Fi sílẹ̀ ní òfìfo láti pa ìsopọ̀ àkọsílẹ̀ ọ̀rọ̀.';
