$string['settings:spend_failover_chain'] = 'Ẹ̀wọ̀n ìdúró';
$string['settings:spend_failover_chain_desc'] = 'Nígbà tí a dé ààlà, [[tutorshort]] ń dán àwọn olùpèsè wọ̀nyí wò lẹ́sẹẹsẹ. Àkọsílẹ̀ kan ní ìlà kọ̀ọ̀kan, ní ìrísí <code>capability:label</code>. Àwọn àmì ń tọ́ka sí àkọsílẹ̀ nínú Àwọn olùpèsè ìfiwéra (fún <code>chat</code> / <code>analytics</code>) tàbí Àwọn olùpèsè ohùn (fún <code>voice</code>). Àwọn ìlà tí ó bẹ̀rẹ̀ pẹ̀lú <code>#</code> jẹ́ àlàyé. Àpẹẹrẹ:<br><code>chat:claude-haiku<br>chat:ollama-local<br>voice:openai-prod<br>analytics:deepseek</code>';
$string['settings:failover_per_call_enabled'] = 'Yíjú sí ìdúró ní ìpè kọ̀ọ̀kan (v5.5.0)';
$string['settings:failover_per_call_enabled_desc'] = 'Nígbà tí a ṣí i, ìpè ìjíròrò kọ̀ọ̀kan ń fi olùpèsè àkọ́kọ́ sínú ìdìpọ̀ ẹ̀wọ̀n ìdúró. Bí àsìkò bá tán nínú ìpè kan tàbí àṣìṣe 5xx bá ṣẹlẹ̀, [[tutorshort]] ń yíjú sí àkọsílẹ̀ tí ó tẹ̀lé nínú <strong>ẹ̀wọ̀n ìdúró</strong> lókè kí ó sì ṣí ìdìmọ́ ìṣẹ́jú 15 fún olùpèsè tí ó kùnà. Ìyípadà kọ̀ọ̀kan ń kọ ìlà àyẹ̀wò (<code>failover_fallthrough</code>); lẹ́yìn tí o ṣí i, wo Ìṣàkóso -> [[tutorshort]] -> Àkọsílẹ̀ àyẹ̀wò láti fi ìdí rẹ̀ múlẹ̀ pé ẹ̀wọ̀n ń ṣiṣẹ́. A pa á ní àbáyanjẹ; ṣí i kìkì lẹ́yìn tí a ti fọwọ́sí ẹ̀wọ̀n náà àti tí ilé-ẹ̀kọ́ rẹ ti fi ìdí rẹ̀ múlẹ̀ pé àwọn àdéhùn ṣíṣe àkọsílẹ̀ tí a nílò wà fún olùpèsè kọ̀ọ̀kan nínú ẹ̀wọ̀n náà.';
$string['settings:failover_timeout_chat'] = 'Ìdúró: àsìkò ìdúró ìjíròrò (ìṣẹ́jú-àáyá)';
$string['settings:failover_timeout_chat_desc'] = 'Ìgbà tí a ó dúró fún token àkọ́kọ́ láti ọwọ́ olùpèsè ìjíròrò kí a tó yíjú. Àbáyanjẹ ìṣẹ́jú-àáyá 8. Iye kékeré ń kúrò lọ́dọ̀ àwọn olùpèsè tí kò yára kíákíá, ṣùgbọ́n ó ń fa ìdágìrì èké púpọ̀ sí i lórí àwọn ìbéèrè tí kò yára fún ìgbà díẹ̀; iye ńlá ń dá ẹ̀wọ̀n dúró lọ́dọ̀ olùpèsè àkọ́kọ́ pẹ́ sí i. A kà á sí kìkì nígbà tí <strong>yíjú sí ìdúró ní ìpè kọ̀ọ̀kan</strong> ń ṣiṣẹ́.';
$string['settings:spend_notify_emails'] = 'Àwọn olùgbà ìkìlọ̀ ìnáwó';
