$string['settings:voice_providers_heading'] = 'Àwọn olùpèsè ohùn (Realtime, TTS, STT)';
$string['settings:voice_providers_heading_desc'] = 'Ṣàtúnṣe olùpèsè API ohùn kan tàbí jù bẹ́ẹ̀ lọ. Àwọn ìṣètò yìí dá dúró láìsí olùpèsè ìjíròrò lókè àti olùpèsè embedding fún RAG — ohùn ní àkọsílẹ̀ olùpèsè tirẹ̀, nítorí pé lọ́wọ́lọ́wọ́ OpenAI àti xAI nìkan ni ó ń pèsè àwọn ibùdó Realtime tí ó dá lórí WebSocket, TTS, àti STT. Lo àwọn àkọsílẹ̀ tí ó ń sọ̀ kalẹ̀ nísàlẹ̀ láti yan olùpèsè tí a ti kọ sílẹ̀ tí yóò mójú tó agbára kọ̀ọ̀kan. Bí a kò bá ṣàlàyé ìlà kankan, ìhùwàsí kọ́kọ́rọ́ kan àtijọ́ ni ó ń ṣiṣẹ́ (kọ́kọ́rọ́ API Realtime lókè tàbí kọ́kọ́rọ́ OpenAI àkọ́kọ́). Ojúlé tí ó ń lo Together AI / Anthropic / DeepSeek / Gemini / Mistral fún ìjíròrò gbọdọ̀ ṣàtúnṣe ìlà kan ní kéré jùlọ níbí kí ohùn lè ṣiṣẹ́.';
$string['settings:voice_active_realtime'] = 'Olùpèsè Realtime tí ó ń ṣiṣẹ́';
$string['settings:voice_active_realtime_desc'] = 'Olùpèsè ohùn tí a ṣàtúnṣe wo ni yóò mójú tó àwọn ìpàdé aṣojú ohùn Realtime.';
$string['settings:voice_active_tts'] = 'Olùpèsè TTS tí ó ń ṣiṣẹ́';
$string['settings:voice_active_tts_desc'] = 'Olùpèsè ohùn tí a ṣàtúnṣe wo ni yóò ka àwọn ìdáhùn AI sókè.';
$string['settings:voice_active_stt'] = 'Olùpèsè STT tí ó ń ṣiṣẹ́';
$string['settings:voice_active_stt_desc'] = 'Olùpèsè wo ni yóò yí ọ̀rọ̀ ẹnu akẹ́kọ̀ọ́ padà sí ọ̀rọ̀ kíkọ. Fi sílẹ̀ ní òfìfo láti fẹ́ ẹ̀rọ ìsìn Whisper tirẹ bí a bá ṣàtúnṣe rẹ̀ nísàlẹ̀, lẹ́yìn náà ìlà àkọ́kọ́ àwọn olùpèsè ohùn tàbí kọ́kọ́rọ́ àtijọ́.';
$string['settings:stt_selfhosted_enabled'] = 'Ṣí àkọsílẹ̀ ọ̀rọ̀ lórí ẹ̀rọ ìsìn tirẹ';
$string['settings:stt_selfhosted_enabled_desc'] = 'Ó ń lo ẹ̀rọ ìsìn Whisper tirẹ nísàlẹ̀ gẹ́gẹ́ bí ọ̀nà ìyípadà ọ̀rọ̀ ẹnu sí ọ̀rọ̀ kíkọ fún ìfilọ́lẹ̀ ohùn àti Soapbox. Ó nílò àdírẹ́sì ẹ̀rọ ìsìn nísàlẹ̀. Nígbà tí a pa á, àkọsílẹ̀ ọ̀rọ̀ ń padà sí ọ̀nà tí a gbàlejò (OpenAI Whisper) tàbí ọ̀nà aṣàwákiri, bí ó tilẹ̀ jẹ́ pé a gbé àdírẹ́sì kalẹ̀.';
$string['settings:stt_selfhosted_warm'] = 'Gbóná nígbà tí ìkọsílẹ̀ Soapbox bẹ̀rẹ̀';
$string['settings:stt_selfhosted_warm_desc'] = 'Nígbà tí a ṣí i, bíbẹ̀rẹ̀ ìkọsílẹ̀ Soapbox ń fi ìbéèrè "ìgbóná" fẹ́ẹ́rẹ́ ránṣẹ́ (bí ó bá ṣeéṣe) sí ẹ̀rọ ìsìn àkọsílẹ̀ ọ̀rọ̀ tirẹ, kí olùgbàlejò tí ó ń dín kù sí òdo (bí àpẹẹrẹ Cloud Run) lè bẹ̀rẹ̀ nígbà tí akẹ́kọ̀ọ́ ṣì ń kọ sílẹ̀ — báyìí ìdádúró ìbẹ̀rẹ̀ tútù wà ní ìpamọ́ kúrò lọ́dọ̀ àkọsílẹ̀ ọ̀rọ̀ tí ó ń ṣiṣẹ́ nígbà ìfisílẹ̀. Kò ní ipa bí a kò bá gbé àdírẹ́sì ẹ̀rọ ìsìn tirẹ kalẹ̀ lókè. A pa á ní àbáyanjẹ.';
$string['settings:voice_tab_enabled'] = 'Ṣí táàbù Ohùn';
$string['settings:voice_tab_enabled_desc'] = 'Ó ń fi táàbù Ohùn hàn nínú pátákó ìtọ́nà ìsàlẹ̀. Nígbà tí a pa á, àwọn akẹ́kọ̀ọ́ ń rí táàbù Ìjíròrò àti Àkọsílẹ̀ nìkan. Àwọn agbára ohùn (ìdánrawò ìjíròrò, ìdánrawò ìpè) ṣì wà ní àrọ́wọ́tó nípasẹ̀ àwọn ìbẹ̀rẹ̀ ìjíròrò bí a bá ṣí wọn ní ọ̀tọ̀ọ̀tọ̀.';
$string['settings:soapbox_heading'] = 'Soapbox';
$string['settings:soapbox_heading_desc'] = 'Ìdánrawò àfihàn ẹnu: bí a ó ṣe kọ àwọn ìkọsílẹ̀ sílẹ̀ àti ìlànà tí a ó fi wọ́n níyì. Ṣí Soapbox fún ìdálẹ́kọ̀ọ́ kọ̀ọ̀kan pẹ̀lú ìtẹ̀ Soapbox nínú abala Ìkọ́nilẹ́kọ̀ọ́.';
