$string['analytics:total_tokens_hint'] = 'Ó ní ìgbàpadà nínú: àwọn ìpè embedding àti reranking, tí wọ́n jẹ gàba lórí iye yìí lórí sàìtì tí RAG ti ń ṣiṣẹ́. A tún ka àwọn ìdáhùn ìjíròrò níbí ṣùgbọ́n ìdá kékeré rẹ̀ ni. Iye ìgbà àti iye akẹ́kọ̀ọ́ níbòmíràn lórí ojú-ìwé yìí ń wọn ìjíròrò nìkan, ìdí nìyí tí àwọn méjèèjì fi lè yàtọ̀ sí ara wọn gan-an.';
$string['coursesettings:auto_open'] = 'Ṣíṣí adáṣiṣẹ́';
