$string['coursesettings:voice_tab'] = 'Táàbù Ohùn';
$string['coursesettings:voice_tab_desc'] = 'Ó ń darí Táàbù Ohùn (àwọn àṣàyàn ohùn nínú pánẹ́ẹ̀lì ètò) fún kọ́ọ̀sì yìí. Ní àìpéye ó ń jogún ètò àgbáyé (lọ́wọ́lọ́wọ́ {$a}).';
$string['coursesettings:voice_tab_help'] = 'Fagilé ètò Táàbù Ohùn àgbáyé fún kọ́ọ̀sì yìí nìkan.';
$string['pricedrift:eol_horizon'] = 'Ààlà ìkìlọ̀ òpin-ìwàláàyè (ọjọ́)';
$string['pricedrift:eol_horizon_desc'] = 'Bí ó ti pẹ́ tó ṣáájú kí a tó bẹ̀rẹ̀ sí í ròyìn ìfẹ̀yìntì àwòṣe tí a ti kéde. Àyẹ̀wò ìyàtọ̀ ń ṣọ́ iye-owó; láìsí èyí kò sí ohun tí ń ṣọ́ ìgbà-ayé àwòṣe, ìfẹ̀yìntì gidi yóò sì dé bí ìdálẹ́kun iṣẹ́ dípò bí ìkìlọ̀ — àwòṣe kan yóò máa ṣiṣẹ́ yóò sì máa gba owó títí di ìgbà tí ó bá dúró, lẹ́yìn náà gbogbo ìpè yóò kùnà lẹ́ẹ̀kan náà. Àìpéye jẹ́ ọjọ́ 60, nítorí pé rírọ́pò àwòṣe iṣẹ́ jẹ́ ìdíje àyẹ̀wò, ìyípadà ètò àti ìtẹ̀jáde, kì í ṣe iṣẹ́ ọ̀sán kan. Ìfẹ̀yìntì tí ọjọ́ rẹ̀ ti kọjá ni a máa ń ròyìn nígbà gbogbo, ohunkóhun tí a bá ṣètò yìí sí.';
$string['pricedrift:eol_surfaces'] = 'Àwọn ojú API tí sàìtì yìí ń pè';
$string['pricedrift:eol_surfaces_desc'] = 'Yíyà sọ́tọ̀ pẹ̀lú ásẹsẹ, fún àpẹẹrẹ <code>gemini-developer-api,openai-api</code>. A kì í kìlọ̀ nípa ìfẹ̀yìntì tí a kéde àyàfi bí a bá kéde rẹ̀ fún ọ̀kan nínú àwọn ojú wọ̀nyí; a ó ṣì fi àwọn tí ó kù hàn, pẹ̀lú àmì pé kì í ṣe tìrẹ. Fi sílẹ̀ ní òfo láti kìlọ̀ nípa gbogbo òpin-ìwàláàyè tí a ti kọ sílẹ̀. Èyí wà nítorí ìjàmbá gidi kan tí ó fẹ́rẹ̀ẹ́ ṣẹlẹ̀: a ròyìn pé gemini-2.5-flash yóò fẹ̀yìntì ní 2026-10-16, èyí tí ó jẹ́ òtítọ́ fún ìgbà-ayé Vertex AI ṣùgbọ́n kì í ṣe fún Gemini Developer API tí plugin yìí ń pè. Kíkìlọ̀ fún ènìyàn lẹ́ẹ̀kan nípa ohun tí kò ṣẹlẹ̀ ń kọ́ wọn láti kọbi-ara sí ìkìlọ̀ tó kàn.';
