$string['settingspage:analytics_link'] = 'Wo Dashboard Analytics';
$string['settingspage:analytics_title'] = 'Dashboard Analytics';
$string['settingspage:rag_explainer'] = 'RAG (Retrieval-Augmented Generation) ń tọ́ka àkóónú kọ́ọ̀sì rẹ, ó sì ń gba àwọn ìpínrọ̀ tí ó bá a mu padà nígbà tí àwọn akẹ́kọ̀ọ́ bá bèèrè ìbéèrè, kí AI lè fún wọn ní ìdáhùn tí ó dá lórí àwọn ohun èlò rẹ. Ó nílò bọ́tìnnì API embedding (a gba OpenAI nímọ̀ràn). Lẹ́yìn tí o bá mú un ṣiṣẹ́, lo ojú-ìwé RAG Admin láti tọ́ka àwọn kọ́ọ̀sì.';
$string['settingspage:realtime_explainer'] = 'Ọ̀nà Ohùn Ìgbàkan-náà (Realtime Voice Mode) ń jẹ́ kí àwọn akẹ́kọ̀ọ́ àti AI bá ara wọn sọ̀rọ̀ ní ẹnu ní ọ̀nà méjèèjì, nípa lílo Realtime API ti OpenAI. Èyí yàtọ̀ sí ọ̀rọ̀-sí-ohùn (TTS) àbáláyé, tí ń ka àwọn ìdáhùn AI sókè. Ohùn Ìgbàkan-náà nílò bọ́tìnnì API ọ̀tọ̀, a sì ń gba owó rẹ̀ ní ìṣẹ́jú ohùn kọ̀ọ̀kan. Lẹ́yìn tí o bá mú un ṣiṣẹ́ ní àgbáyé, o lè yí i padà fún kọ́ọ̀sì kọ̀ọ̀kan lórí ojú-ìwé ètò kọ́ọ̀sì náà.';
