$string['modelregistry:err_noeolsurface'] = 'Ọjọ́ òpin ìgbà ìlò nílò surface API tí a kéde rẹ̀ fún. Ìfẹ̀yìntì tí a kéde fún surface kan kò kan òmíràn, àti ọjọ́ tí kò ní surface tí a kọ sílẹ̀ ni ọ̀nà tí ìkéde ìgbésí-ayé awoṣe tí o kò tilẹ̀ ń pè fi ń di ìdágìrì àṣìṣe nípa ìdálẹ́kun iṣẹ́. Lo \'any\' bí ó bá kan gbogbo ibi.';
$string['modelregistry:field_eol_date'] = 'Ọjọ́ òpin ìgbà ìlò';
$string['modelregistry:field_eol_date_help'] = 'Ọjọ́ ìfẹ̀yìntì tàbí ọjọ́ pípa á tí a kéde, ní ọ̀nà YYYY-MM-DD. Fi sílẹ̀ ní òfìfo nígbà tí a kò tí ì kéde òpin ìgbà ìlò kankan — òfìfo túmọ̀ sí pé a kò kéde rẹ̀, kì í ṣe pé ó wà ní ààbò. A ń kà á gẹ́gẹ́ bí ọjọ́ kàlẹ́ndà ní UTC, kì í ṣe ní àgbègbè àkókò tìrẹ, kí gbogbo ẹni tí ó bá ka ìlà yìí lè gbìmọ̀ fún ọ̀sẹ̀ kan náà.';
$string['modelregistry:field_eol_surface'] = 'Ohun tí òpin ìgbà ìlò kàn';
$string['modelregistry:field_eol_surface_help'] = 'Surface API wo ni a kéde ọjọ́ náà fún: <code>gemini-developer-api</code>, <code>vertex-ai</code>, <code>openai-api</code>, <code>azure-openai</code>, <code>bedrock</code>, tàbí <code>any</code> fún gbogbo surface. Ó jẹ́ dandan nígbàkúgbà tí a bá tẹ ọjọ́ kan sí i, kì í sì í ṣe ìwé lásán: a ròyìn pé gemini-2.5-flash ń fẹ̀yìntì ní 2026-10-16, ṣùgbọ́n ìṣẹ̀lẹ̀ ìgbésí-ayé Vertex AI ni ìyẹn, kì í ṣe Gemini Developer API tí ojú òpó yìí ń pè. Láìsí surface náà, ọjọ́ yẹn ń gbé ìdágìrì ìdálẹ́kun iṣẹ́ dìde nípa awoṣe tí kò lọ sí ibikíbi. Ṣe àkọsílẹ̀ àwọn surface tí ojú òpó yìí ń pè gan-an lábẹ́ Drift iye kí àwọn tí kì í ṣe tìrẹ lè jẹ́ ìròyìn lásán.';
$string['modelregistry:finding_eol'] = 'Awoṣe tí ń dé òpin ìgbà ìlò';
