$string['privacy:metadata:bench'] = 'Àwọn ìṣiṣẹ́ benchmark olùpèsè: àwọn àbájáde ìfiwéra awoṣe tí olùṣàkóso ojú òpó ti ṣẹ̀dá. Data ti ara ẹni kan ṣoṣo ni ìdámọ̀ olùṣàkóso tí ó bẹ̀rẹ̀ ìṣiṣẹ́ náà. Ìṣètò ojú òpó ni àwọn ìlà wọ̀nyí, kì í ṣe data ti ara ẹni nípa akẹ́kọ̀ọ́, nítorí náà a kì í fi wọ́n sínú ìjáde data, a kì í sì í pa wọ́n rẹ́ nígbà tí olùmúlò bá béèrè pípa data rẹ̀ run.';
$string['privacy:metadata:bench:createdby'] = 'Olùṣàkóso ojú òpó tí ó bẹ̀rẹ̀ ìṣiṣẹ́ benchmark yìí. Ó jẹ́ òfìfo nígbà tí a bá bẹ̀rẹ̀ ìṣiṣẹ́ náà láti ìlà àṣẹ.';
$string['privacy:metadata:models'] = 'Àwọn ìforúkọsílẹ̀ registry awoṣe: àwọn ìfagilé iye àti agbára fún awoṣe kọ̀ọ̀kan tí olùṣàkóso ojú òpó ń tọ́jú. Data ti ara ẹni kan ṣoṣo ni ìdámọ̀ olùṣàkóso tí ó fi ìforúkọsílẹ̀ náà pamọ́ kẹ́yìn. Ìṣètò ojú òpó ni àwọn ìlà wọ̀nyí, kì í ṣe data ti ara ẹni nípa akẹ́kọ̀ọ́, nítorí náà a kì í fi wọ́n sínú ìjáde data, a kì í sì í pa wọ́n rẹ́ nígbà tí olùmúlò bá béèrè pípa data rẹ̀ run.';
$string['privacy:metadata:models:addedby'] = 'Olùṣàkóso ojú òpó tí ó fi ìforúkọsílẹ̀ registry awoṣe yìí pamọ́ kẹ́yìn. Ó jẹ́ òfìfo nígbà tí feed iye aládàáṣiṣẹ́ bá kọ ìforúkọsílẹ̀ náà.';
$string['privacy:metadata:pricesrc'] = 'Àwọn ìtumọ̀ feed iye: àwọn àkójọ iye olùtajà tí olùṣàkóso ojú òpó ti ṣètò plugin náà láti gbà. Data ti ara ẹni kan ṣoṣo ni ìdámọ̀ olùṣàkóso tí ó fi feed náà kún un. Ìṣètò ojú òpó ni àwọn ìlà wọ̀nyí, kì í ṣe data ti ara ẹni nípa akẹ́kọ̀ọ́, nítorí náà a kì í fi wọ́n sínú ìjáde data, a kì í sì í pa wọ́n rẹ́ nígbà tí olùmúlò bá béèrè pípa data rẹ̀ run.';
$string['privacy:metadata:pricesrc:addedby'] = 'Olùṣàkóso ojú òpó tí ó fi feed iye yìí kún un. Ó jẹ́ òfìfo nígbà tí feed náà bá wá pẹ̀lú plugin náà.';
$string['privacy:metadata:sbx_assign'] = 'Àwọn iṣẹ́ àyànfúnni ìgbékalẹ̀ Soapbox: àwọn iṣẹ́ tí olùkọ́ ṣètò fún ẹ̀kọ́ kan. Data ti ara ẹni kan ṣoṣo ni ìdámọ̀ òṣìṣẹ́ tí ó ṣàtúnṣe iṣẹ́ àyànfúnni náà kẹ́yìn. Ìṣètò ẹ̀kọ́ ni àwọn ìlà wọ̀nyí, kì í ṣe data ti ara ẹni nípa akẹ́kọ̀ọ́, nítorí náà a kì í fi wọ́n sínú ìjáde data, a kì í sì í pa wọ́n rẹ́ nígbà tí olùmúlò bá béèrè pípa data rẹ̀ run — bí bẹ́ẹ̀ kọ́, ìyẹn yóò yí iṣẹ́ àyànfúnni tí àwọn akẹ́kọ̀ọ́ mìíràn ṣì ń ṣiṣẹ́ lé lórí padà.';
